----------------------------------------------------
33. Combining Multiple Window Functions in One Query 
----------------------------------------------------


--“Monthly revenue generated by each staff member.”

select 
	staff_id,
	date_trunc('month', payment_date) as month,
	sum(amount)
from payment
group by staff_id, date_trunc('month', payment_date)
order by staff_id, month;

--For each staff member, show their monthly revenue and compare it with the previous month’s revenue.

select 
	staff_id,
	date_trunc('month', payment_date) as month,
	sum(amount) as revenue,
	
	coalesce(
	lag(sum(amount)) over (
		partition by staff_id
		order by date_trunc('month', payment_date)
	), 0) as previous_month_revenue
	
from payment

group by 
	staff_id, date_trunc('month', payment_date)
order by
	staff_id, month;

--How each staff member is performing over time, how they compare to their own past performance, 
--and how their monthly performance ranks against other months.

select
	staff_id,
	date_trunc('month', payment_date) as month,
	sum(amount) as revenue,

	rank() over (
		partition by staff_id
		order by sum(amount) desc
	) as rank_per_revenue_per_month,
	
	lag(sum(amount)) over (
		partition by staff_id
		order by date_trunc('month', payment_date)
	) as previous_month_revenue,	
	
	sum(amount) - 
	lag(sum(amount)) over (
		partition by staff_id
		order by date_trunc('month', payment_date)
	) as difference_from_previous_month,	
	
	lead(sum(amount)) over (
		partition by staff_id
		order by date_trunc('month', payment_date)
	) as next_month_revenue,
	
	sum(sum(amount)) over (
		partition by staff_id
		order by date_trunc('month', payment_date)
	) as running_total

from payment
group by
	staff_id, date_trunc('month', payment_date)
order by
	staff_id, month;




with monthly_revenue as
	(
	select
		staff_id,
		date_trunc('month', payment_date) as month,
		sum(amount) as revenue
	from payment
	group by staff_id, date_trunc('month', payment_date)
)

select 
	staff_id,
	month,
	revenue,
	
	rank() over (
		partition by staff_id
		order by revenue desc
	) as revenue_rank,
	
	lag(revenue) over (
		partition by staff_id
		order by month
	) as previous_month_revenue,	
	
	revenue - 
	lag(revenue) over (
		partition by staff_id
		order by month
	) as difference_from_previous_month,	
	
	lead(revenue) over (
		partition by staff_id
		order by month
	) as next_month_revenue,
	
	sum(revenue) over (
		partition by staff_id
		order by month
	) as running_total
	
from monthly_revenue
order by staff_id, month;




-------------------------------------
34 — Window Function Inside CASE when
-------------------------------------


--Show me which staff members are improving, declining, or stable compared to last month.

select
	p.staff_id,
	f.first_name || ' ' || f.last_name as full_name,
	date_trunc('month', p.payment_date) as month,
	sum(p.amount),
	
	lag(sum(p.amount)) over (
			partition by p.staff_id
			order by date_trunc('month', p.payment_date)
		) as previous_payment,
	
	case
		when lag(sum(p.amount)) over (
			partition by p.staff_id
			order by date_trunc('month', p.payment_date)) is null
		then 'First_Month'
			
		when sum(p.amount) > 
		lag(sum(p.amount)) over (
			partition by p.staff_id
			order by date_trunc('month', p.payment_date)
		) 
		then 'Improving'
		
		when sum(p.amount) < 
		lag(sum(p.amount)) over (
			partition by p.staff_id
			order by date_trunc('month', p.payment_date)
		) 
		then 'Declining'
		
		else 'Stable'
		
	end as Status
	
from payment p
join staff f
	on p.staff_id = f.staff_id
group by p.staff_id, f.first_name, f.last_name, date_trunc('month', p.payment_date);

/*
In above Query there is a problem 

1. SQL must calculate the same window function repeatedly.
		If you need a window function more than once:
		do not recalculate it.
		Calculate it once and reuse it.
*/

Below is a professional Query

select 
	staff_id,
	full_name,
	month,
	revenue,
	previous_revenue,
	
	case
		when previous_revenue is null
			then 'First_Month'
		
		when revenue > previous_revenue
			then 'Improving'
		
		when revenue < previous_revenue
			then 'Declining'	
			
		else 'Stable'
	end as performance_status
	
from
	(
	select
		p.staff_id,
		f.first_name || ' ' || f.last_name as full_name,
		date_trunc('month', p.payment_date) as month,
		sum(p.amount) as revenue,
		
		lag(sum(p.amount)) over (
				partition by p.staff_id
				order by date_trunc('month', p.payment_date)
			) as previous_revenue
			
	from payment p
	join staff f
		on f.staff_id = p.staff_id 
	
	group by 
		p.staff_id,
		f.first_name,
		f.last_name,
		date_trunc('month', p.payment_date)
	) x;
	
	
	

Business Question

The management wants a detailed monthly performance evaluation report for each staff member
to understand revenue trends, consistency, and relative performance over time.

For each staff member and month, calculate:

1. The total monthly revenue generated.
2. The previous month’s revenue for comparison.
3. The percentage growth or decline compared to the previous month.
4. Classify monthly performance trend as:
	* First Month (no prior data)
	* High Growth (more than 20% increase)
	* Moderate Growth (0% to 20% increase)
	* Declining (decrease in revenue)
5. The average monthly revenue of each staff member across all months.
6. Classify performance relative to their average as:
	* Above Average
	* Below Average
	* Average Performer
7. Rank each month of a staff member based on revenue performance.
8. Categorize each month based on rank as:
	* Best Month
	* Top Performer Month
	* Regular Month

select
	staff_id,
	full_name,
	month,
	revenue,
		revenue_rank,

	case
		when revenue_rank = 1 
			then 'Best_Month'
		
		when revenue_rank between 2 and 3
			then 'Top_Performer_Month'
		
		else 'Regular Month'
	end as rank_tatus,
	
	
	previous_revenue,

	round(
		(
			(revenue - previous_revenue)
			/
			nullif(previous_revenue, 0)
		) * 100,
		2
	) as growth_precentage,
	
	case
		when previous_revenue is null
			then 'First_Month'
			
		when (
		(revenue - previous_revenue)
			/
			nullif(previous_revenue, 0)
		) * 100 > 20
			then 'High Growth'
			
		when (
		(revenue - previous_revenue)
			/
			nullif(previous_revenue, 0)
		) * 100 between 0 and 20
			then 'Moderate Growth'
			
		when (
		(revenue - previous_revenue)
			/
			nullif(previous_revenue, 0)
		) * 100 < 0
			then'Declining'
		
	end as performance_status,
	
	average_monthly_revenue,

	
	case
		when revenue > average_monthly_revenue
			then 'Above Average'
			
		when revenue < average_monthly_revenue
			then 'Below Average'
		
		else 'Average Performer'
	end as average_performance_status
	
from 
	(
	select
		p.staff_id,
		f.first_name || ' ' || f.last_name as full_name,
		date_trunc('month', p.payment_date) as month,
		sum(p.amount) as revenue,
		
		lag(sum(p.amount)) over (
				partition by p.staff_id
				order by date_trunc('month', p.payment_date)
			) as previous_revenue,
			
		avg(sum(p.amount)) over (
			partition by p.staff_id
		) as average_monthly_revenue,
		
		rank() over (
			partition by p.staff_id
			order by sum(p.amount) desc
		) as revenue_rank
			
	from payment p
	join staff f
		on f.staff_id = p.staff_id 
	
	group by 
		p.staff_id,
		f.first_name,
		f.last_name,
		date_trunc('month', p.payment_date)
	) x;

	
	

